/**
 * Banks for the material culture pack: cuisine, crafts, trade goods, dress, buildings, music, games, land.
 * Keyed by environment (biome or layer), sphere, genre, culture trait and faith doctrine. No em dashes,
 * lines under 120 characters. Apostrophes are typographic so strings stay single-quoted.
 */
import type { Genre } from '../../../gen/genre';
import type { DoctrineKind } from '../../../gen/types';
import type { TraitKey } from '../profile';

export type CraftT = [name: string, goods: string[], mark: string];
export type GoodT = [name: string, kind: string, value: number];
export type DishT = [name: string, tag: string, ingredients: string[]];
export type GameT = [name: string, rule: string];

// ---------------- environments ----------------

